const systems={windows:{file:'Windows11_x64.iso',format:'NTFS · UEFI:NTFS',mode:'Установочный USB для UEFI'},linux:{file:'linuxmint-cinnamon.iso',format:'Гибридный ISO · ext4 persistence',mode:'Linux Live · сохранять изменения'},dos:{file:'FD14-LiteUSB.zip',format:'Официальный FreeDOS · IMG внутри ZIP',mode:'DOS · BIOS / CSM'}};
const tabs=[...document.querySelectorAll('[data-system]')];
function select(tab){const data=systems[tab.dataset.system];tabs.forEach(item=>{item.setAttribute('aria-selected',String(item===tab));item.tabIndex=item===tab?0:-1});document.getElementById('demo-file').textContent=data.file;document.getElementById('demo-format').textContent=data.format;document.getElementById('demo-mode').textContent=data.mode}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();select(tabs[next]);tabs[next].focus()}})});select(tabs[0]);
